<?php
declare(strict_types=1);
function qa180_loyalty_manual(App $app,array $user,array $tenant):void {
    echo '<section class="card admin-card"><h2>Cómo usar Fidelización</h2><details open><summary>Configurar, acumular y canjear</summary><ol><li><strong>Elige la regla.</strong> Puntos por monto, cantidad de compras o dinero acumulado. Ejemplo: 1 punto por cada ₡1.000 y un premio al alcanzar 10 puntos.</li><li><strong>Elige el premio.</strong> Un porcentaje de descuento, un monto fijo de un solo uso o un producto del negocio. Selecciona un producto si ese es el premio y activa el programa.</li><li><strong>Identifica al cliente en la venta.</strong> Consumidor final no acumula beneficios. Las ventas de caja acumulan al confirmar su cobro; un pedido web recibido en caja no vuelve a acumular por entregarlo. Un pedido web antiguo sin cuenta de caja acumula al marcarse entregado.</li><li><strong>Consulta el progreso.</strong> El cliente ve sus puntos, premios y códigos en su cuenta. El dueño puede revisar los movimientos desde la ficha del cliente o Reportes → Fidelización.</li><li><strong>Canjea una vez.</strong> El cliente puede introducir su código FIEL- al confirmar un pedido web. Para una entrega presencial del premio, valida su código aquí y entrega el beneficio: el canje manual registra el uso, sin cobrar ni modificar automáticamente otra cuenta de venta. No vuelvas a canjear un premio aplicado en el pedido.</li></ol><p>La tarjeta de regalo recargable mantiene un saldo; el premio de fidelización con monto fijo permite un solo uso. Usa los nombres de cada sección para distinguirlos.</p></details><a class="btn btn-light" href="'.e(url('admin/reportes?dataset=loyalty')).'">Historial de fidelización</a> <a class="btn btn-light" href="'.e(url('admin/clientes-buscar')).'">Buscar cliente</a></section>';
}
function qa180_loyalty_customer(App $app,array $tenant,int $customer):void {
    $account=$app->one('SELECT * FROM loyalty_accounts WHERE tenant_id=? AND user_id=?',[$tenant['id'],$customer]);echo '<h3>Fidelización del cliente</h3>';
    if(!$account){echo '<p>Este cliente aún no tiene movimientos. Identifícalo en una venta elegible para empezar a acumular.</p>';return;}
    echo '<p>Puntos: '.e($account['points_balance']).' · Compras: '.e($account['purchases_balance']).' · Consumo: '.money((float)$account['spend_balance']).'</p><h4>Movimientos recientes</h4><div class="table-wrap"><table class="table"><tr><th>Fecha</th><th>Detalle</th><th>Puntos</th><th>Compras</th><th>Monto</th></tr>';
    foreach($app->all('SELECT created_at,description,points_delta,purchases_delta,spend_delta FROM loyalty_ledger WHERE account_id=? ORDER BY id DESC LIMIT 100',[$account['id']]) as $row)echo '<tr><td>'.e($row['created_at']).'</td><td>'.e($row['description']).'</td><td>'.e($row['points_delta']).'</td><td>'.e($row['purchases_delta']).'</td><td>'.money((float)$row['spend_delta']).'</td></tr>';echo '</table></div><h4>Premios</h4>';foreach($app->all('SELECT code,status,expires_at FROM loyalty_rewards WHERE account_id=? ORDER BY id DESC LIMIT 50',[$account['id']]) as $row)echo '<p><code>'.e($row['code']).'</code> · '.e($row['status']==='available'&&strtotime($row['expires_at'])<time()?'Vencido':ui_label_qa($row['status'])).' · '.e($row['expires_at']).'</p>';
}
